import java.util.Scanner;

class Employee {
    protected double basicSalary;

    public Employee(double basicSalary) {
        this.basicSalary = basicSalary;
    }

    public double calculateSalary() {
        return basicSalary;
    }
}

class Manager extends Employee {
    public Manager(double basicSalary) {
        super(basicSalary);
    }

    @Override
    public double calculateSalary() {
        return basicSalary + 5000;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextDouble()) {
            sc.close();
            return;
        }

        double basicSalary = sc.nextDouble();
        sc.close();

        Employee emp = new Employee(basicSalary);
        Manager mgr = new Manager(basicSalary);

        System.out.println("Employee Salary: " + (int) emp.calculateSalary());
        System.out.println("Manager Salary: " + (int) mgr.calculateSalary());
    }
}
